#!/usr/bin/env node
/**
 * Sync AGENTS.md → CLAUDE.md, .cursor/rules/index.mdc, .github/copilot-instructions.md
 *
 * AGENTS.md is the canonical source. Run this script after editing AGENTS.md
 * (the Husky pre-commit hook runs it automatically when AGENTS.md is in the
 * commit). The derived files are generated with a clear AUTO-GENERATED header
 * — never edit them by hand.
 *
 * Cursor reads `.cursor/rules/*.mdc` (the legacy top-level `.cursorrules` is
 * deprecated); Copilot reads `.github/copilot-instructions.md`; Cursor, Copilot,
 * and Codex also read AGENTS.md natively. Referenced in M09 lecture 9.C.
 */

import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname } from 'node:path';

const AGENTS = await readFile('AGENTS.md', 'utf8');

const generatedHeader = (clientName) => `<!--
  AUTO-GENERATED from AGENTS.md by scripts/sync-instructions.mjs
  Do NOT edit this file directly. Edit AGENTS.md and re-run the sync.
  Generated for: ${clientName}
-->

`;

// Cursor `.mdc` rule files use YAML frontmatter; alwaysApply attaches the rule
// to every request. The AUTO-GENERATED note goes in the body, below the fence.
const cursorMdcHeader = `---
description: Project conventions for AI coding agents (source of truth: AGENTS.md)
alwaysApply: true
---

<!--
  AUTO-GENERATED from AGENTS.md by scripts/sync-instructions.mjs
  Do NOT edit this file directly. Edit AGENTS.md and re-run the sync.
  Generated for: Cursor (.cursor/rules)
-->

`;

async function writeWithDirs(path, content) {
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, content);
}

await writeWithDirs('CLAUDE.md', generatedHeader('Claude Code') + AGENTS);
await writeWithDirs('.cursor/rules/index.mdc', cursorMdcHeader + AGENTS);
await writeWithDirs('.github/copilot-instructions.md', generatedHeader('GitHub Copilot') + AGENTS);

console.info(
  '✓ Synced AGENTS.md → CLAUDE.md + .cursor/rules/index.mdc + .github/copilot-instructions.md',
);
